          "group": "During articleship"
        }
      },
      {
        "gate": "uploaded",
        "files": [
          "articleship-program-v3/day-6/Industrial training guide.pdf"
        ],
        "resource": {
          "title": "Industrial training guide",
          "type": "pdf",
          "view_storage_path": "articleship-program-v3/day-6/Industrial training guide.pdf",
          "copy": true,
          "group": "During articleship"
        }
      },
      {
        "gate": "uploaded",
        "files": [
          "articleship-program-v3/day-6/CA Final study guidelines.pdf"
        ],
        "resource": {
          "title": "CA Final study guidelines",
          "type": "pdf",
          "view_storage_path": "articleship-program-v3/day-6/CA Final study guidelines.pdf",
          "copy": true,
          "group": "During articleship"
        }
      },
      {
        "gate": "uploaded",
        "files": [
          "articleship-program-v3/day-6/Post Articleship CVs.pdf"
        ],
        "resource": {
          "title": "Post Articleship CVs",
          "type": "pdf",
          "view_storage_path": "articleship-program-v3/day-6/Post Articleship CVs.pdf",
          "group": "Post Articleship CVs"
        }
      }
    ]
  }
]'::jsonb) AS s(value)
), current_rows AS (
    SELECT v.video_number, v.day_number, to_jsonb(v.resources) AS resources
    FROM public.videos AS v
    WHERE v.course = 'msc-articleship-program'
), items AS (
    SELECT (p.session->>'video_number')::int AS video_number,
           (p.session->>'day_number')::int AS day_number,
           r.ord, r.item
    FROM plan AS p
    CROSS JOIN LATERAL jsonb_array_elements(p.session->'resources') WITH ORDINALITY AS r(item, ord)
), kept AS (
    SELECT i.video_number, i.ord, i.item->'resource' AS resource
    FROM items AS i
    LEFT JOIN current_rows AS c ON c.video_number = i.video_number AND c.day_number = i.day_number
    WHERE CASE i.item->>'gate'
        WHEN 'always' THEN true
        WHEN 'uploaded' THEN NOT EXISTS (
            SELECT 1 FROM jsonb_array_elements_text(i.item->'files') AS f(path)
            WHERE NOT EXISTS (
                SELECT 1 FROM storage.objects AS o WHERE o.bucket_id = 'industrial-training-mastery-resources' AND o.name = f.path
            )
        )
        WHEN 'kept' THEN EXISTS (
            SELECT 1
            FROM jsonb_array_elements(CASE WHEN jsonb_typeof(c.resources) = 'array' THEN c.resources ELSE '[]'::jsonb END) AS e(value)
            WHERE e.value->>'title' = i.item->'resource'->>'title'
        )
        ELSE false
    END
), built AS (
    SELECT p.session->>'course' AS course,
           (p.session->>'video_number')::int AS video_number,
           p.session->>'title' AS title,
           CASE WHEN (SELECT count(*) FROM kept AS k WHERE k.video_number = (p.session->>'video_number')::int)
                     = jsonb_array_length(p.session->'resources')
                THEN p.session->>'description'
                ELSE p.session->>'description_partial'
           END AS description,
           (p.session->>'day_number')::int AS day_number,
           COALESCE((SELECT jsonb_agg(k.resource ORDER BY k.ord) FROM kept AS k
                     WHERE k.video_number = (p.session->>'video_number')::int), '[]'::jsonb) AS resources
    FROM plan AS p
), incoming AS (
    SELECT * FROM json_populate_recordset(NULL::public.videos, (SELECT json_agg(b) FROM built AS b))
)
UPDATE public.videos AS existing
SET title = incoming.title,
    description = incoming.description,
    resources = incoming.resources
FROM incoming
WHERE existing.course = incoming.course
  AND existing.day_number = incoming.day_number
  AND existing.video_number = incoming.video_number;

COMMIT;
